/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isFieldArray = require( '@stdlib/plot/vega/base/assert/is-field-array' );
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var aggregateOperations = require( '@stdlib/plot/vega/transform/aggregate/operations' );
var contains = require( '@stdlib/array/base/assert/contains' ).factory;
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'vega:aggregate-transform:set:'+prop.name );
var isOperation = contains( aggregateOperations() );


// MAIN //

/**
* Sets the data fields for which to compute aggregate functions.
*
* @private
* @param {FieldArray} value - input value
* @throws {TypeError} must be an array of field instances
* @returns {void}
*/
function set( value ) {
	var field;
	var i;

	if ( !isFieldArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be an array of fields. Value: `%s`.', prop.name, value ) );
	}
	for ( i = 0; i < value.length; i++ ) {
		field = value[ i ];
		if ( !isOperation( field.field ) ) {
			throw new TypeError( format( 'invalid assignment. `%s` must be one of the following: "%s". Value: `%s`.', prop.name, join( aggregateOperations(), '", "' ), value[ i ] ) );
		}
	}
	if ( !hasEqualValues( value, this[ prop.private ] ) ) {
		this._removeChangeListeners( this[ prop.private ] );
		debug( 'Current value: %s. New value: %s.', JSON.stringify( this[ prop.private ] ), JSON.stringify( value ) );
		this[ prop.private ] = copy( value );
		this.emit( 'change', changeEvent( prop.name ) );
		this._addChangeListeners( this[ prop.private ] );
	}
}


// EXPORTS //

module.exports = set;
